import { getRequestConfig } from 'next-intl/server';
import type { AbstractIntlMessages } from 'next-intl';
import { cookies, headers } from 'next/headers';
import { LOCALES, DEFAULT_LOCALE, type Locale } from '@quetzal/i18n';
import { FORCED_LOCALE_HEADER, readForcedLocale } from '@/lib/forced-locale';
// merged.<locale>.json = core catalogue + every module catalogue (generated by `pnpm --filter @quetzal/i18n merge`)
import frMessages from '@quetzal/i18n/catalogues/merged.fr.json';
import enMessages from '@quetzal/i18n/catalogues/merged.en.json';
import esMessages from '@quetzal/i18n/catalogues/merged.es.json';

const messagesByLocale: Record<Locale, AbstractIntlMessages> = {
  fr: frMessages as AbstractIntlMessages,
  en: enMessages as AbstractIntlMessages,
  es: esMessages as AbstractIntlMessages,
};

function isLocale(value: string | undefined): value is Locale {
  return typeof value === 'string' && (LOCALES as readonly string[]).includes(value);
}

export default getRequestConfig(async () => {
  const cookieStore = await cookies();
  const cookieLocale = cookieStore.get('NEXT_LOCALE')?.value;
  // Un seul appel a headers() : la langue forcee et accept-language y vivent
  // toutes deux.
  const requestHeaders = await headers();
  const acceptLang = requestHeaders.get('accept-language');
  const browserLocale = acceptLang?.split(',')[0]?.split('-')[0];
  // La langue d'une partie prime sur celle de l'utilisateur, qui prime sur
  // celle de l'appareil. C'est l'ordre voulu : l'enseignante decide de la
  // langue de SA partie, sinon chacun garde la sienne.
  const forced = readForcedLocale(requestHeaders.get(FORCED_LOCALE_HEADER));
  const locale: Locale =
    forced ??
    (isLocale(cookieLocale)
      ? cookieLocale
      : isLocale(browserLocale)
        ? browserLocale
        : DEFAULT_LOCALE);
  return { locale, messages: messagesByLocale[locale] };
});
